"""Real pointer-capture seeking on the roll, including shifted and truncated pages."""
import argparse,json
from pathlib import Path
from playwright.sync_api import sync_playwright
p=argparse.ArgumentParser();p.add_argument('--output',type=Path,required=True);out=p.parse_args().output.resolve();out.mkdir(parents=True,exist_ok=False);root=Path(__file__).resolve().parents[1]
def geometry(page):return page.evaluate('''()=>{const t=window.__SKY_STUDIO_TEST__,c=document.getElementById('rollCanvas'),r=c.getBoundingClientRect(),f=t.rollFrame(),g=t.rollPlotGeometry(r,f);return {...f,...g,x:r.x,y:r.y,height:r.height}}''')
def point(g,f):return g['x']+g['left']+f*g['plotW'],g['y']+g['top']+30
with sync_playwright() as pw:
 b=pw.chromium.launch(channel='msedge',headless=True);page=b.new_page(viewport={'width':1366,'height':768});errors=[];page.on('pageerror',lambda e:errors.append(str(e)));page.goto((root/'SkyMusicStudio_Standalone.html').as_uri());page.locator('.card-play').first.click();assert page.locator('#rollCanvas').evaluate('e=>getComputedStyle(e).cursor')=='crosshair';original=page.evaluate('JSON.stringify(window.__SKY_STUDIO_TEST__.state.project.score)');records=[]
 for sec in [8,10,12,20]:
  page.locator('#rollWindow').select_option(str(sec));page.locator('#seekSlider').evaluate("e=>{e.value=0;e.dispatchEvent(new Event('input'))}");g=geometry(page)
  page.mouse.click(*point(g,.25));assert abs(page.evaluate('window.__SKY_STUDIO_TEST__.state.position')-g['windowMs']*.25)<.1
  page.mouse.move(*point(g,.25));page.mouse.down();page.mouse.move(*point(g,.75),steps=8);assert abs(page.evaluate('window.__SKY_STUDIO_TEST__.state.position')-g['windowMs']*.75)<.1;assert abs(geometry(page)['begin']-g['begin'])<.1
  page.mouse.move(g['x']-20,point(g,.75)[1]);assert abs(page.evaluate('window.__SKY_STUDIO_TEST__.state.position')-g['begin'])<.1;page.mouse.up();assert not page.evaluate('document.getElementById("rollCanvas").hasPointerCapture(1)')
  page.locator('#rollSeekSlider').evaluate("e=>{e.value=37000;e.dispatchEvent(new Event('input'))}");shifted=geometry(page);page.mouse.click(*point(shifted,.6));assert abs(geometry(page)['begin']-shifted['begin'])<.1;assert abs(page.evaluate('window.__SKY_STUDIO_TEST__.state.position')-(shifted['begin']+shifted['windowMs']*.6))<.1
  page.locator('#seekSlider').evaluate("e=>{e.value=e.max;e.dispatchEvent(new Event('input'))}");tail=geometry(page);page.mouse.move(*point(tail,.4));page.mouse.down();page.mouse.move(tail['x']+tail['left']+tail['plotW']+30,point(tail,.4)[1],steps=8);page.mouse.up();assert abs(page.evaluate('window.__SKY_STUDIO_TEST__.state.position-window.__SKY_STUDIO_TEST__.state.project.durationMs'))<.1;assert abs(geometry(page)['begin']-tail['begin'])<.1;records.append({'seconds':sec,'shiftedBegin':shifted['begin'],'tail':tail})
 page.locator('#restartBtn').click();page.locator('#playBtn').click();page.wait_for_function('window.__SKY_STUDIO_TEST__.state.isPlaying');g=geometry(page);page.mouse.click(*point(g,.5));assert not page.evaluate('window.__SKY_STUDIO_TEST__.state.isPlaying');position=page.evaluate('window.__SKY_STUDIO_TEST__.state.position');page.wait_for_timeout(100);assert page.evaluate('window.__SKY_STUDIO_TEST__.state.position')==position;assert page.locator('#seekSlider').input_value()==str(round(position));assert page.locator('.beat.active').get_attribute('data-index')==str(page.evaluate('window.__SKY_STUDIO_TEST__.state.selected'));assert page.evaluate('JSON.stringify(window.__SKY_STUDIO_TEST__.state.project.score)')==original;page.screenshot(path=str(out/'dragged-roll.png'));assert not errors,errors
 # Real touch events use browser pointer capture, rather than synthetic pointer IDs.
 mobile=b.new_context(viewport={'width':390,'height':844},is_mobile=True,has_touch=True);touch=mobile.new_page();touch.goto((root/'SkyMusicStudio_Standalone.html').as_uri());touch.locator('.card-play').first.click();touch.locator('#rollCanvas').scroll_into_view_if_needed();g=geometry(touch);client=mobile.new_cdp_session(touch)
 x,y=point(g,.2);client.send('Input.dispatchTouchEvent',{'type':'touchStart','touchPoints':[{'x':x,'y':y}]});x,y=point(g,.7);client.send('Input.dispatchTouchEvent',{'type':'touchMove','touchPoints':[{'x':x,'y':y}]});client.send('Input.dispatchTouchEvent',{'type':'touchEnd','touchPoints':[]});assert abs(touch.evaluate('window.__SKY_STUDIO_TEST__.state.position')-(g['begin']+g['windowMs']*.7))<3;mobile.close();b.close()
(out/'results.json').write_text(json.dumps({'passed':True,'windows':records,'playbackPauses':True,'scoreUnchanged':True,'touch':True,'errors':errors},indent=2),'utf-8');print('PASS click/drag/pointer capture, 4 windows, shifted and final pages, playback pause, synchronized UI, unmodified score and real touch')
